local({
  x <- as.numeric(T2E1)
  case_when(x == 96 ~ 0, x >= 0 & x <= 24 ~ x, .default = NA_real_)
})

local({
  items <- cbind(T2O1C, T2O1P, T2O1S, T2O1W, T2O1Y, T2O1AA, T2O1HH, T2O1JJ, T2O1OO, T2O1PP, T2O1TT)
  items[!items %in% 0:2] <- NA
  if_else(rowSums(!is.na(items)) >= 9, rowMeans(items, na.rm = TRUE), NA_real_)
})

local({
  items <- cbind(T2O1K, T2O1T, T2O1Z, T2O1FF, T2O1KK, T2O1MM, T2O1SS)
  items[!items %in% 0:2] <- NA
  rowSums(items)
})

local({
  lb <- as.numeric(NBQ3LB)
  oz <- as.numeric(NBQ3OZ)
  if_else(lb < 98 & oz < 98, (lb * 16 + oz) * 28.35, NA_real_)
})
